"""Municipality name -> 10-digit Census county-subdivision GEOID, for every
state whose towns are real governments.

`_fips.py` answers "which county is this?" for the forty-odd states where the
county is the unit that runs elections. This module answers the same question
one level down, for the twenty-one where it is not. New England has no county
election administration at all -- Maine's absentee file is keyed by
"RES MUNICIPALITY" and there is no county on the row -- and Michigan, Wisconsin,
Minnesota, Pennsylvania and the rest of the strong-MCD belt report by township
or jurisdiction alongside their counties.

THE KEY IS THE GEOID, AND THE GEOID CONTAINS THE COUNTY. A county subdivision's
GEOID is state(2) + county(3) + cousub(5): Auburn, Maine is `2300102060`, which
is state 23, county 001 (Androscoggin), subdivision 02060. That is why town rows
can roll up to county rows EXACTLY -- `county_of(geoid)` is a string slice, not
an inferred crosswalk. Getting municipality NAMES to counties is what defeated
the first pass at Maine; with the GEOID the county is already in the key.

Source: the vintage-2020 Census county-subdivision code file,

    https://www2.census.gov/geo/docs/reference/codes2020/national_cousub2020.txt

which is the same family as the `national_county2020.txt` that `_fips.py`
carries. It is vendored here rather than read from the theme's shipped town
geometry so the pipeline owns its own reference data -- but the two agree
exactly: the GEOIDs below are, state for state, the identical set to the
`cousub_fp` values in the site's `assets/forecasts/towns/<st>.json`
(ME 530, NH 259, VT 255, MA 351, CT 169, RI 39, MI 1539, WI 1910 -- zero on
either side of the difference). Every town we publish therefore has a shape to
draw it in.

Only the twenty-one MCD states are carried. Everywhere else a "county
subdivision" is a Census County Division -- a statistical box drawn by the
Census Bureau with no clerk, no ballots and no legal existence -- and putting
those names in the table would only invite a false match. `covered()` reports
which states are here; a state that is not returns None like any other miss.

Two rules make it safe to trust, and they are `_fips.py`'s rules verbatim:

* An unrecognised name returns `None`. Never guessed at, never fuzzy matched.
* An AMBIGUOUS name returns `None` too. This is not a rare corner here the way
  it is for counties -- Wisconsin has 420 names that are both a town and a city
  or village, Michigan 248 -- so a source that does not say which one it means
  cannot be joined, and the caller must raise SchemaDrift. Maine is nearly clean
  but not quite: "Lincoln" is both a town in Penobscot County and a plantation
  in Oxford County, "Unity" is both a town in Waldo and an unorganized territory
  in Kennebec, and "Rangeley" is both a town and a plantation in Franklin. Those
  three resolve to nothing and are reported as unmapped rather than being
  assigned to whichever is bigger.

**"UT" is deliberately NOT treated as a synonym for "Twp".** Maine's file names
individual unorganized townships ("Argyle Twp", "T1 R9 WELS"); the Census names
unorganized *territories*, and while a few of those are one township ("Argyle
UT") most are aggregations of many ("Central Aroostook UT", "North Penobscot
UT"). Equating the two would silently place a dozen townships' ballots in one of
them. So Maine's unorganized territory does not map, which is the correct answer
until Maine publishes a code alongside the name -- see `docs/town-level-data.md`.
"""

from __future__ import annotations

import re
from functools import lru_cache

from ..normalize import county_fips as _compose_county
from . import _fips

#: Class words the Census appends to a subdivision's name. Longest first: the
#: 118 Michigan "charter township" entries must not be shortened to "X charter".
#: Measured, not guessed -- these are every trailing class word that occurs in
#: the table below.
_SUFFIXES = (
    " charter township", " township", " plantation", " reservation",
    " municipality", " precinct", " location", " borough", " village",
    " purchase", " town", " city", " grant", " gore", " ut",
)

#: How sources abbreviate a class word. Registered as additional EXACT aliases
#: (so "Lincoln Plt" hits "Lincoln plantation" head-on) rather than as fuzzy
#: matching. "ut" is absent on purpose -- see the module docstring.
_ABBREVIATIONS = {
    "township": ("twp", "twp."),
    "plantation": ("plt", "plt."),
}


def _norm(raw: str) -> str:
    """Lowercase, collapse whitespace, drop punctuation that varies by source."""
    text = " ".join(str(raw).strip().lower().split())
    return text.replace(".", "").replace("'", "").replace("`", "")


def _squash(text: str) -> str:
    """Alphanumerics only -- joins "DeWitt"/"De Witt" and "LaSalle"/"La Salle"."""
    return re.sub(r"[^a-z0-9]", "", text)


def _short(text: str) -> str:
    for suffix in _SUFFIXES:
        if text.endswith(suffix):
            return text[: -len(suffix)].strip()
    return text


def _saint_variants(text: str) -> set[str]:
    """"St Albans" and "Saint Albans" are the same place in every source but ours."""
    out = {text}
    if text.startswith("st "):
        out.add("saint " + text[3:])
    if text.startswith("saint "):
        out.add("st " + text[6:])
    return out


def _abbreviated(text: str) -> set[str]:
    """"lincoln plantation" -> also "lincoln plt"."""
    out = {text}
    for word, forms in _ABBREVIATIONS.items():
        if text.endswith(" " + word):
            stem = text[: -len(word)]
            out.update(_norm(stem + form) for form in forms)
    return out


def _entries(state: str):
    """(canonical name, 10-digit GEOID) for every subdivision in `state`."""
    for packed in CENSUS_COUSUBS[state]:
        county, _, rest = packed.partition("|")
        prefix = _compose_county(state, county)
        for item in rest.split("|"):
            yield item[6:], prefix + item[:5]


@lru_cache(maxsize=None)
def _table(state: str) -> dict[str, tuple[str, str]]:
    """alias -> (10-digit GEOID, canonical census name), ambiguities removed.

    Built per state on first use. The national table is 25,151 subdivisions and
    a run touches one or two states, so building all of them at import would be
    most of a second spent on rows nobody asked for.
    """
    exact: dict[str, tuple[str, str]] = {}
    clashed: set[str] = set()
    loose: dict[str, set[str]] = {}
    loose_name: dict[str, tuple[str, str]] = {}

    for name, geoid in _entries(state):
        full = _norm(name)
        for base in _saint_variants(full):
            for spelling in _abbreviated(base):
                for variant in (spelling, _squash(spelling)):
                    if variant in exact and exact[variant][0] != geoid:
                        # Two subdivisions whose FULL names collide once
                        # punctuation is normalised. Neither may keep the alias.
                        clashed.add(variant)
                    exact[variant] = (geoid, name)
        short = _short(full)
        if short != full:
            for key in _saint_variants(short):
                for variant in (key, _squash(key)):
                    loose.setdefault(variant, set()).add(geoid)
                    loose_name[variant] = (geoid, name)

    for variant in clashed:
        exact.pop(variant, None)

    for alias, geoids in loose.items():
        # A bare name two subdivisions both claim ("Lincoln" the town and
        # "Lincoln" the plantation) is dropped rather than resolved.
        if len(geoids) == 1 and alias not in exact and alias not in clashed:
            exact[alias] = loose_name[alias]
    return exact


def covered(state: str) -> bool:
    """Is `state` one of the twenty-one with real county subdivisions?"""
    return state.upper() in CENSUS_COUSUBS


def states() -> tuple[str, ...]:
    return tuple(sorted(CENSUS_COUSUBS))


def lookup(state: str, name: str | None) -> tuple[str, str] | None:
    """Return (10-digit cousub GEOID, canonical census name) for a municipality.

    `None` means "not recognised, or recognised as ambiguous" -- the caller must
    raise SchemaDrift, or exclude the row and COUNT it, rather than guess.
    """
    if name is None:
        return None
    table = _table(state.upper()) if covered(state) else None
    if table is None:
        return None
    key = _norm(name)
    if not key:
        return None
    return table.get(key) or table.get(_squash(key))


def county_of(geoid: str) -> str:
    """The 5-digit county FIPS embedded in a 10-digit cousub GEOID.

    This is the whole reason town rows can roll up to county rows exactly. It is
    a slice, not a crosswalk, so it cannot drift and cannot guess.
    """
    text = str(geoid).strip()
    if len(text) != 10 or not text.isdigit():
        raise ValueError(f"not a 10-digit county-subdivision GEOID: {geoid!r}")
    return text[:5]


def names(state: str) -> tuple[str, ...]:
    """Every canonical subdivision name for a state, in census order."""
    return tuple(name for name, _ in _entries(state.upper()))


def county_name_of(state: str, county_fips: str) -> str:
    """The census name of a 5-digit county FIPS, for a town->county rollup.

    `CountyDay` publishes a name beside the FIPS, and an adapter that derives its
    county rows from `county_of()` has the code but not the name. Reads the same
    2020 census table `_fips.lookup` is built from, so the two agree by
    construction.
    """
    code = str(county_fips).strip()[-3:]
    for name, county_code in _fips.CENSUS_COUNTIES.get(state.upper(), ()):
        if county_code == code:
            return name
    return ""


# --------------------------------------------------------------------------
# Carrying town rows on a FetchResult.
#
# `adapters.base.FetchResult` has fields for the state, county and demographic
# tables and predates this one. Adding a fourth field there would touch the file
# every adapter in the tree imports, so town rows ride as an attribute instead
# and these three functions are the only way to put them on or take them off.
# The cost is that `FetchResult.stamp()` does not know about them, so an adapter
# that emits town rows must call `_towns.stamp()` as well -- forget it and
# `schema._prov` refuses the write by name, loudly, rather than publishing rows
# with no provenance.
# --------------------------------------------------------------------------
ROWS_ATTR = "town_rows"


def attach(result, rows):
    """Put TownDay rows on a FetchResult and return it."""
    setattr(result, ROWS_ATTR, list(rows))
    return result


def rows_of(result) -> list:
    """The TownDay rows on a FetchResult, or [] -- most adapters have none."""
    return list(getattr(result, ROWS_ATTR, None) or ())


def stamp(result, provenance):
    """Apply provenance to every town row that did not set its own."""
    for row in rows_of(result):
        if row.provenance is None:
            row.provenance = provenance
    return result


